function mkText(content,{family="Tenor Sans",style="Regular",size=12,color={r:0,g:0,b:0},spacing=0,lh=null}={}){
  const t=figma.createText(); t.fontName={family,style}; t.characters=content; t.fontSize=size; t.fills=[{type:'SOLID',color}];
  if(spacing) t.letterSpacing={value:spacing,unit:'PIXELS'};
