  return t;
}
function autoFrame(name,{dir='VERTICAL',gap=0,pad=0,w=null,align='MIN',counter='MIN',bg=null}={}){
  const f=figma.createFrame(); f.name=name; f.layoutMode=dir; f.itemSpacing=gap;
  f.paddingLeft=f.paddingRight=pad; f.paddingTop=f.paddingBottom=pad;
  f.primaryAxisAlignItems=align; f.counterAxisAlignItems=counter;
  f.primaryAxisSizingMode='AUTO'; f.counterAxisSizingMode= w? 'FIXED':'AUTO';
  if(w){ f.resize(w, f.height); }
  f.fills= bg? [{type:'SOLID',color:bg}]:[];
  return f;
}
