// helper for a product card setter (find text layers inside and photo)
async function setCard(cardInst, photoName, brand, name, price){
  const photoHolder = cardInst.findOne(n=>n.name==="Photo"||n.type==="RECTANGLE"||n.type==="INSTANCE"&&n.name.startsWith("Product_"));
  // find text nodes by order
  const texts = cardInst.findAll(n=>n.type==="TEXT");
  // Try to assign heuristically: texts[0]=brand,1=name,2=price if 3 texts exist
  if(texts.length>=3){
    texts[0].characters=brand; texts[1].characters=name; texts[2].characters="$"+price;
  }
  return cardInst;
}

// Build a simple product card manually (safer than guessing instance structure)
async function productCard(photoCompName,brand,name,price,w,h){
  const card = figma.createFrame(); card.resize(w,h); card.fills=[]; card.layoutMode='VERTICAL'; card.primaryAxisSizingMode='AUTO'; card.counterAxisSizingMode='FIXED'; card.itemSpacing=8;
  let photo;
  try{ photo = (await compById(photoCompName)).createInstance(); }catch(e){ photo=figma.createRectangle(); photo.fills=[{type:'SOLID',color:LIGHT}]; }
  photo.resize(w,Math.round(w*1.3)); card.appendChild(photo);
  const heart = await inst("Icon_Heart", w-28, 8); heart.resize(20,20); card.appendChild(heart); heart.x=w-28; heart.y=8;
  const brandT = txt(brand,11,GRAY); card.appendChild(brandT);
  const nameT = txt(name,13,BLACK); nameT.resize(w,32); nameT.textAutoResize='HEIGHT'; card.appendChild(nameT);
  const priceT = txt("$"+price,13,BLACK); card.appendChild(priceT);
  return card;
}

