async function textField(label,value,x,y){
  const tf = (await compById("Text Field")).createInstance();
  tf.x=x; tf.y=y;
  // try set text inside
  function walk(n){ if(n.type==='TEXT'){ return n;} if('children' in n){ for(const c of n.children){ const r=walk(c); if(r) return r;} } return null; }
  const t = walk(tf);
  if(t){ figma.loadFontAsync(t.fontName).then(()=>{ t.characters = value||label; }); }
  return tf;
}

